20	// DEVDESK-149 step 2: column 0 of the templates table is the activity column
21	// (Rule 125). A row answers for two registry targets: its slug (sync) and its
22	// scan directory (scan). The phase is read at render, never rebuilt per frame.
23	
24	const indCtx = "ctx"
25	
26	// indFixture is a catalog with one entry of each source kind. The names are
27	// sorted API, Img, Web.
28	func indFixture(t *testing.T) Model {
29		t.Helper()
30		t.Setenv("HOME", t.TempDir())
31		t.Setenv("USERPROFILE", t.TempDir())
32		api := entry("api", "API")
33		web := template.Entry{Slug: "web", Name: "Web", Source: template.Source{Kind: template.KindLocal, Path: "/srv/web-src"}}
34		img := template.Entry{Slug: "img", Name: "Img", Source: template.Source{Kind: template.KindOCI, URL: "registry.example.com/", Path: "acme/img", Ref: "1.0"}}
35		m := opened(t, api, web, img)
36		return send(t, m, testutil.Resize(120, 30))
37	}
38	
39	func indRun(kind jobs.Kind, state jobs.ItemState, target string) jobs.Run {
40		run := jobs.NewRun(kind, command.ViewTemplates, indCtx, "x", target)
41		run.Items[0].State = state
42		return run
43	}
44	
45	func indFailure(kind jobs.Kind, target, detail string) jobs.Failure {
46		return jobs.Failure{
47			FailureKey: jobs.FailureKey{Kind: kind, Target: jobs.TargetKey(target), Context: indCtx},
48			Display:    target, Detail: detail, At: time.Now(),
49		}
50	}
51	
52	func snapshot(t *testing.T, m Model, runs []jobs.Run, failures []jobs.Failure) Model {
53		t.Helper()
54		return send(t, m, jobs.ChangedMsg{Runs: runs, Failures: failures, Context: indCtx})
55	}
56	
57	func scanDirOf(t *testing.T, slug string) string {
58		t.Helper()
59		dir, err := template.ScanDir(slug)
60		if err != nil {
61			t.Fatal(err)
62		}
63		return dir
64	}
65	
66	func lineOf(t *testing.T, m Model, name string) string {
67		t.Helper()
68		for _, l := range strings.Split(m.View(), "\n") {
69			if strings.Contains(l, name) {
70				return l
71			}
72		}
73		t.Fatalf("no rendered line holds %q:\n%s", name, m.View())
74		return ""
75	}
76	
77	func hasAnyGlyph(line string) bool {
78		for _, s := range indicator.States() {
79			if g := indicator.Glyph(s, true); g != "" && strings.Contains(line, g) {
80				return true
81			}
82		}
83		return strings.Contains(line, indicator.Glyph(indicator.Running, false))
84	}
85	
86	// fgPrefix is the escape sequence that sets a style's foreground, as rendered.
87	func fgPrefix(s lipgloss.Style) string {
88		out := s.Render("x")
89		return out[:strings.Index(out, "x")]
90	}
91	
92	func TestColumnZeroIsTheActivityColumn(t *testing.T) {
93		m := indFixture(t)
94		shapes := m.table.Shapes()
95		if len(shapes) == 0 {
96			t.Fatal("no column")
97		}
98		c := shapes[0]
99		if !c.Indicator {
100			t.Error("column 0 is not built by datatable.IndicatorColumn (no Indicator)")
101		}
102		if c.Title != "" {
103			t.Errorf("column 0 titled %q, want untitled", c.Title)
104		}
105		if c.Sizing != datatable.SizingFixed || c.MinWidth != datatable.IconColumnWidth {
106			t.Errorf("column 0 sizing/min = %v/%d, want SizingFixed/%d", c.Sizing, c.MinWidth, datatable.IconColumnWidth)
107		}
108		if c.Less || c.Search {
109			t.Errorf("column 0 declares Less=%v Search=%v, want neither", c.Less, c.Search)
110		}
111	}
