113	func TestAnIdleRowShowsItsSourceKindGlyph(t *testing.T) {
114		m := indFixture(t)
115		for name, kind := range map[string]template.Kind{"API": template.KindGit, "Web": template.KindLocal, "Img": template.KindOCI} {
116			line := lineOf(t, m, name)
117			if !strings.Contains(line, kindGlyph(kind)) {
118				t.Errorf("%s: the rest icon %q is not rendered:\n%s", name, kindGlyph(kind), line)
119			}
120			if hasAnyGlyph(line) {
121				t.Errorf("%s: an idle row shows an activity glyph:\n%s", name, line)
122			}
123		}
124	}
