126	func TestEachActivityStateRendersItsGlyphOnItsRow(t *testing.T) {
127		// The scan directory is computed under the isolated HOME of indFixture, so
128		// the cases are built after it.
129		tests := []struct {
130			name  string
131			build func(t *testing.T) ([]jobs.Run, []jobs.Failure)
132			blink bool
133			want  string
134		}{
135			{"sync queued, phase on", func(*testing.T) ([]jobs.Run, []jobs.Failure) {
136				return []jobs.Run{indRun(jobs.KindSync, jobs.ItemQueued, "api")}, nil
137			}, true, indicator.Glyph(indicator.Queued, true)},
138			{"sync running, phase on", func(*testing.T) ([]jobs.Run, []jobs.Failure) {
139				return []jobs.Run{indRun(jobs.KindSync, jobs.ItemRunning, "api")}, nil
140			}, true, indicator.Glyph(indicator.Running, true)},
141			{"sync running, phase off", func(*testing.T) ([]jobs.Run, []jobs.Failure) {
142				return []jobs.Run{indRun(jobs.KindSync, jobs.ItemRunning, "api")}, nil
143			}, false, indicator.Glyph(indicator.Running, false)},
144			{"scan running on the scan directory, phase on", func(t *testing.T) ([]jobs.Run, []jobs.Failure) {
145				return []jobs.Run{indRun(jobs.KindScan, jobs.ItemRunning, scanDirOf(t, "api"))}, nil
146			}, true, indicator.Glyph(indicator.Running, true)},
147			{"scan running on the scan directory, phase off", func(t *testing.T) ([]jobs.Run, []jobs.Failure) {
148				return []jobs.Run{indRun(jobs.KindScan, jobs.ItemRunning, scanDirOf(t, "api"))}, nil
149			}, false, indicator.Glyph(indicator.Running, false)},
150			{"sync failed, phase on", func(*testing.T) ([]jobs.Run, []jobs.Failure) {
151				return nil, []jobs.Failure{indFailure(jobs.KindSync, "api", "sync failed — check logs")}
152			}, true, indicator.Glyph(indicator.Failed, true)},
153			{"sync failed, phase off", func(*testing.T) ([]jobs.Run, []jobs.Failure) {
154				return nil, []jobs.Failure{indFailure(jobs.KindSync, "api", "sync failed — check logs")}
155			}, false, indicator.Glyph(indicator.Failed, false)},
156			{"scan failed, phase on", func(t *testing.T) ([]jobs.Run, []jobs.Failure) {
157				return nil, []jobs.Failure{indFailure(jobs.KindScan, scanDirOf(t, "api"), "scan failed — check logs")}
158			}, true, indicator.Glyph(indicator.Failed, true)},
159			{"scan failed, phase off", func(t *testing.T) ([]jobs.Run, []jobs.Failure) {
160				return nil, []jobs.Failure{indFailure(jobs.KindScan, scanDirOf(t, "api"), "scan failed — check logs")}
161			}, false, indicator.Glyph(indicator.Failed, false)},
162		}
163		for _, tc := range tests {
164			t.Run(tc.name, func(t *testing.T) {
165				m := indFixture(t)
166				runs, failures := tc.build(t)
167				m = snapshot(t, m, runs, failures)
168				m = send(t, m, jobs.FrameMsg{Blink: tc.blink})
169				line := lineOf(t, m, "API")
170				if !strings.Contains(line, tc.want) {
171					t.Errorf("row lacks %q:\n%s", tc.want, line)
172				}
173				if strings.Contains(line, kindGlyph(template.KindGit)) {
174					t.Errorf("the activity glyph shares the cell with the rest icon:\n%s", line)
175				}
176				for _, other := range []string{"Web", "Img"} {
177					if l := lineOf(t, m, other); hasAnyGlyph(l) {
178						t.Errorf("an untouched row (%s) shows an activity glyph:\n%s", other, l)
179					}
180				}
181			})
182		}
183	}
