185	func TestAFailedRowIsFixedAndFailureColoured(t *testing.T) {
186		testutil.TrueColor(t)
187		m := indFixture(t)
188		// Web is not the selected row (the cursor opens on the first one, API).
189		m = snapshot(t, m, nil, []jobs.Failure{indFailure(jobs.KindSync, "web", "sync failed — check logs")})
190		want := fgPrefix(lipgloss.NewStyle().Foreground(theme.ColorActivityFailed)) + indicator.Glyph(indicator.Failed, true)
191		for _, blink := range []bool{true, false} {
192			m = send(t, m, jobs.FrameMsg{Blink: blink})
193			if line := lineOf(t, m, "Web"); !strings.Contains(line, want) {
194				t.Errorf("blink=%v: the failed glyph is not in the failure colour:\n%q", blink, line)
195			}
196		}
197	}
