225	func TestADoneSyncGoesBackToTheRestIcon(t *testing.T) {
226		m := indFixture(t)
227		m = snapshot(t, m, []jobs.Run{indRun(jobs.KindSync, jobs.ItemRunning, "api")}, nil)
