239	func TestANewRunOnAFailedSlugReplacesTheFailureGlyph(t *testing.T) {
240		m := indFixture(t)
241		m = snapshot(t, m, nil, []jobs.Failure{indFailure(jobs.KindSync, "api", "sync failed — check logs")})
242		if !strings.Contains(lineOf(t, m, "API"), indicator.Glyph(indicator.Failed, true)) {
