361	// ── Q1-B: the Synced column says "syncing" while a sync of the row runs ──────
362	
363	func TestTheSyncedColumnSaysSyncingWhileASyncRuns(t *testing.T) {
364		testutil.TrueColor(t)
365		syncedAt := time.Now().Add(-3 * 24 * time.Hour)
366		setup := func(t *testing.T) Model {
367			m := indFixture(t)
368			m.syncedAt = map[string]time.Time{"api": syncedAt, "web": syncedAt, "img": syncedAt}
369			m.rebuild()
370			return m
371		}
372		age := theme.TimeAgo(syncedAt)
373	
374		t.Run("running sync: plain text in DimStyle", func(t *testing.T) {
375			m := snapshot(t, setup(t), []jobs.Run{indRun(jobs.KindSync, jobs.ItemRunning, "api")}, nil)
376			line := lineOf(t, m, "API")
377			if !strings.Contains(line, "syncing") {
378				t.Fatalf("the Synced cell does not say syncing:\n%s", line)
379			}
380			if strings.Contains(line, age) {
381				t.Errorf("the stale age %q is still shown while syncing:\n%s", age, line)
382			}
383			if !strings.Contains(line, fgPrefix(theme.DimStyle)+"syncing") {
384				t.Errorf("syncing is not dim:\n%q", line)
385			}
386			if other := lineOf(t, m, "Web"); strings.Contains(other, "syncing") || !strings.Contains(other, age) {
387				t.Errorf("another row changed its Synced cell:\n%s", other)
388			}
389		})
390		t.Run("queued sync: the age stays", func(t *testing.T) {
391			m := snapshot(t, setup(t), []jobs.Run{indRun(jobs.KindSync, jobs.ItemQueued, "api")}, nil)
392			line := lineOf(t, m, "API")
393			if strings.Contains(line, "syncing") || !strings.Contains(line, age) {
394				t.Errorf("a queued sync must leave the age:\n%s", line)
395			}
396		})
397		t.Run("running scan: the age stays", func(t *testing.T) {
398			m := setup(t)
399			m = snapshot(t, m, []jobs.Run{indRun(jobs.KindScan, jobs.ItemRunning, scanDirOf(t, "api"))}, nil)
400			line := lineOf(t, m, "API")
401			if strings.Contains(line, "syncing") || !strings.Contains(line, age) {
402				t.Errorf("a scan must leave the age:\n%s", line)
403			}
404		})
405		t.Run("sync done: the age is back", func(t *testing.T) {
406			m := snapshot(t, setup(t), []jobs.Run{indRun(jobs.KindSync, jobs.ItemDone, "api")}, nil)
407			if line := lineOf(t, m, "API"); strings.Contains(line, "syncing") {
408				t.Errorf("syncing outlived the sync:\n%s", line)
409			}
410		})
411	}
