1	package templates
2	
3	import (
4		"context"
5		"fmt"
6		"log"
7	
8		tea "github.com/charmbracelet/bubbletea"
9	
10		"github.com/anthnel/devdesk/internal/cache"
11		"github.com/anthnel/devdesk/internal/command"
12		"github.com/anthnel/devdesk/internal/jobs"
13		"github.com/anthnel/devdesk/internal/scan"
14		"github.com/anthnel/devdesk/internal/template"
15		sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
16		"github.com/anthnel/devdesk/internal/ui/shortcut"
17	)
18	
19	// Scanning a template is scanning what it would put in a repository, and it is
20	// worth doing *before* that: a secret in a template ends up in every repository
21	// made from it.
22	//
23	// The template is fetched, written to a fixed directory of the scan cache
24	// (template.Materialize), and that directory is scanned like any other. It is a
25	// directory scan on purpose: the result is cached by path, so it appears in the
26	// `:sec` inventory and opens in the same results view, with nothing new to
27	// build. What is not reused is the workspaces list — the copy is not in it, and
28	// nothing here pretends it is.
29	
30	const (
31		reasonNoScanner   = "No scanner available — install Trivy or Gitleaks, or check scan settings"
32		reasonScanRunning = "A scan of this template is already running"
33	)
34	
35	// scanFunc runs the scanners over a directory. It is a field of the model so a
36	// test can answer without running Trivy.
37	type scanFunc func(ctx context.Context, dir string, opts scan.ScanOptions) (*scan.Result, error)
38	
39	func runScanners(ctx context.Context, dir string, opts scan.ScanOptions) (*scan.Result, error) {
40		return scan.NewScanner(opts).Scan(ctx, dir, scan.TargetDirectory)
41	}
42	
43	// ScanStartingMsg says the scan left the queue and holds a worker. The cancel
44	// goes with it — it is created inside the Cmd, and stored by the registry in the
45	// same Update that marks the item running, so there is no window where the row
46	// is running and cannot be stopped (D7).
47	type ScanStartingMsg struct {
48		Path   string
49		Cancel context.CancelFunc
50	}
51	
52	// ScanCompleteMsg is the scan's outcome.
53	type ScanCompleteMsg struct {
54		Slug   string
55		Name   string
56		Path   string
57		Counts scan.SeverityCounts
58		// Partial is set when a stage failed and nothing was found: the scan ran, and
59		// "no findings" would be a claim about something it did not look at.
60		Partial bool
61		Err     error
62	}
63	
64	func (m ScanStartingMsg) Transition() jobs.Transition {
65		return jobs.Transition{Kind: jobs.KindScan, Target: m.Path, State: jobs.ItemRunning, Cancel: m.Cancel}
66	}
67	
68	func (m ScanCompleteMsg) Transition() jobs.Transition {
69		t := jobs.Transition{Kind: jobs.KindScan, Target: m.Path, State: jobs.ItemDone}
70		if m.Err != nil {
71			t.State = jobs.ItemFailed
72			t.Detail = "scan failed — check logs"
73		}
74		return t
75	}
76	
77	// Compile-time proof that both can be applied to the registry: a message added
78	// without it is routed, updates the view, and leaves its row spinning for the
79	// life of the session.
80	var (
81		_ jobs.Reporter = ScanStartingMsg{}
82		_ jobs.Reporter = ScanCompleteMsg{}
83	)
84	
85	// scanJob is everything the scan needs, read in Update and carried into the
86	// Cmd, which runs on another goroutine and must not reach back into the model
87	// (Rule 110).
88	type scanJob struct {
89		entry template.Entry
90		creds template.Credentials
91		cache template.Cache
92		opts  scan.ScanOptions
93		run   scanFunc
94	}
95	
96	// scanTemplateCmd fetches, materializes and scans one template.
97	//
98	// contextName travels with the command rather than being read at the end (D68):
99	// the counts belong to the context the scan was launched in, whatever the user
100	// is looking at when it lands.
101	func scanTemplateCmd(job scanJob, contextName string) tea.Cmd {
102		dir, dirErr := template.ScanDir(job.entry.Slug)
103		ctx, cancel := context.WithCancel(context.Background())
104	
105		return tea.Sequence(
106			func() tea.Msg { return ScanStartingMsg{Path: dir, Cancel: cancel} },
107			func() tea.Msg {
108				defer cancel()
109				complete := ScanCompleteMsg{Slug: job.entry.Slug, Name: job.entry.Name, Path: dir}
110	
111				if dirErr != nil {
112					complete.Err = dirErr
113					return complete
114				}
115				result, err := job.scanOnce(ctx, contextName)
116				if err != nil {
117					log.Printf("ERROR [templates] scan %s: %v", job.entry.Slug, err)
118					complete.Err = err
119					return complete
120				}
121				complete.Counts = result.Counts
122				complete.Partial = len(result.Errors) > 0 && result.TotalFindings() == 0
123				return complete
124			},
125		)
126	}
127	
128	func (j scanJob) scanOnce(ctx context.Context, contextName string) (*scan.Result, error) {
129		files, err := j.cache.Fetch(ctx, j.entry.Slug, j.entry.Source, j.creds)
130		if err != nil {
131			return nil, fmt.Errorf("fetching the template: %w", err)
132		}
133		dir, err := template.Materialize(j.entry.Slug, files)
134		if err != nil {
135			return nil, fmt.Errorf("writing the template: %w", err)
136		}
137		result, err := j.run(ctx, dir, j.opts)
138		if err != nil {
139			return nil, err
140		}
141		if _, err := cache.StoreWorkspaceScan(contextName, dir, result); err != nil {
142			// The scan happened and its counts are reported; only the cache write
143			// failed, and `:sec` will not show it.
144			log.Printf("ERROR [templates] store scan %s: %v", j.entry.Slug, err)
145		}
146		return result, nil
147	}
148	
149	// scanOptions assembles the options for a template: the configured scanners,
150	// and no CI score — a template is not a repository with a pipeline to grade, and
151	// plumber would go looking for a remote it does not have.
152	func (m Model) scanOptions() scan.ScanOptions {
153		opts := scan.OptionsFromConfig(m.config)
154		opts.Categories.CI.Enabled = false
155		opts.Detected = m.deps
156		return opts
157	}
158	
159	// scannerState says whether a scan can run at all on this machine. Not knowing
160	// is not knowing that not: until the check comes back the key stays lit, since
161	// greying it for a few frames only to un-grey it reads as a fault (Rule 130).
162	func (m Model) scannerState() shortcut.Availability {
163		if m.deps == nil || m.deps.CanScan(m.scanOptions().Categories, scan.TargetDirectory) {
164			return shortcut.Availability{}
165		}
166		return shortcut.Unavailable(reasonNoScanner)
167	}
168	
169	// scanning reports whether a scan of this directory is live, wherever it was
170	// started — the registry is one bookkeeping.
171	func (m Model) scanning(dir string) bool { return m.working(jobs.KindScan, dir) }
172	
173	// working reports whether a job of this kind is live on this target.
174	func (m Model) working(kind jobs.Kind, target string) bool {
175		for _, run := range jobs.Unfinished(m.jobs) {
176			if run.Kind != kind {
177				continue
178			}
179			for _, item := range run.Items {
180				if item.Target == target && !item.State.Terminal() {
181					return true
182				}
183			}
184		}
185		return false
186	}
187	
188	// startScan launches a scan of the selected template.
189	func (m Model) startScan() (tea.Model, tea.Cmd) {
190		if reason := m.refusal(m.availability().Scan); reason != "" {
191			cmd := m.footer.Warn(reason)
192			return m, cmd
193		}
194		entry, _ := m.selectedEntry()
195		dir, err := template.ScanDir(entry.Slug)
196		if err != nil {
197			log.Printf("ERROR [templates] scan directory for %s: %v", entry.Slug, err)
198			cmd := m.footer.Error("Could not scan the template — check logs")
199			return m, cmd
200		}
201	
202		job := scanJob{
203			entry: entry,
204			creds: template.CredentialsFor(m.config, m.secrets, entry.Source),
205			cache: m.cache,
206			opts:  m.scanOptions(),
207			run:   m.scanner,
208		}
209		run := jobs.NewRun(jobs.KindScan, command.ViewTemplates, "", entry.Name, dir)
210		return m, jobs.StartInContext(run, func(contextName string) tea.Cmd {
211			return scanTemplateCmd(job, contextName)
212		})
213	}
214	
215	func (m Model) handleJobsChanged(msg jobs.ChangedMsg) (tea.Model, tea.Cmd) {
216		m.jobs = msg.Runs
217		return m, nil
218	}
219	
220	// handleFrameMsg takes the animation's frame for the footer spinner.
221	func (m Model) handleFrameMsg(msg jobs.FrameMsg) (tea.Model, tea.Cmd) {
222		m.footer.SetSpinnerFrame(msg.RenderedFrame)
223		return m, nil
224	}
225	
226	// handleScanComplete says how the scan ended. The counts are in the footer and
227	// the report is in `:sec`, where this directory is listed like any other scanned
228	// target.
229	func (m Model) handleScanComplete(msg ScanCompleteMsg) (tea.Model, tea.Cmd) {
230		// A scan reads the template through the cache, which may have made the copy.
231		refresh := m.refreshSynced()
232		var cmd tea.Cmd
233		switch {
234		case msg.Err != nil:
235			cmd = m.footer.Error("Scan of " + msg.Name + " failed — check logs")
236		case msg.Partial:
237			cmd = m.footer.Warn("Scanned " + msg.Name + ", but a scan stage failed — check logs")
238		default:
239			cmd = m.footer.Info(scanSummary(msg))
240		}
241		return m, tea.Batch(refresh, cmd)
242	}
243	
244	// scanSummary is the one line a finished scan leaves.
245	func scanSummary(msg ScanCompleteMsg) string {
246		c := msg.Counts
247		if c.Critical+c.High+c.Medium+c.Low == 0 {
248			return "Scanned " + msg.Name + " — no findings"
249		}
250		return fmt.Sprintf("Scanned %s — %d critical, %d high, %d medium, %d low — :sec for the report",
251			msg.Name, c.Critical, c.High, c.Medium, c.Low)
252	}
253	
254	// jobsStatus is the footer's derived line while work is live.
255	func (m Model) jobsStatus() sharedcomponents.Status {
256		if text := sharedcomponents.JobsStatusLine(m.jobs, command.ViewTemplates); text != "" {
257			return sharedcomponents.Status{Text: text, Spinner: true}
258		}
259		return sharedcomponents.Status{}
260	}
